"use client";

import React, { useEffect, useState } from "react";
import jsPDF from "jspdf";
import { renderToString } from "react-dom/server";
import { NdaPDF } from "@/components/nda/nda-pdf";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

export default function NdaApprovalPage() {
  const [loading, setLoading] = useState(false);
  const [clients, setClients] = useState<any[]>([]);
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [form, setForm] = useState<any>({
    title: "NDA Approval",
    clientName: "",
    disclosingParty: "",
    receivingParty: "",
    effectiveDate: new Date().toISOString().split("T")[0],
    term: "2 years",
    scope: "",
    confidentialDefinition: "",
    exclusions: "",
    signatureName: "",
    date: new Date().toISOString().split("T")[0],
  });

  const update = (k: string, v: any) => setForm((s: any) => ({ ...s, [k]: v }));

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const res = await fetch('/api/clients');
        if (!res.ok) throw new Error('Failed to fetch clients');
        const items = await res.json();
        if (!mounted) return;
        setClients(items || []);
      } catch (e) {
        console.error(e);
      }
    })();
    return () => { mounted = false; };
  }, []);

  useEffect(() => {
    if (!selectedClientId) return;
    const c = clients.find((x) => (x._id ?? x.id) === selectedClientId);
    if (!c) return;
    setForm((s: any) => ({ ...s, clientName: c.name || c.companyName || s.clientName }));
  }, [selectedClientId, clients]);

  const generatePdf = async () => {
    setLoading(true);
    try {
      const doc = new jsPDF({ unit: "mm", format: "a4", orientation: "portrait" });

      try {
        const { loadNotoSansForJsPDF } = await import("@/lib/pdf-fonts");
        const family = await loadNotoSansForJsPDF(doc, "NotoSans");
        if (family) {
          try { doc.setFont(family); } catch (e) {}
        }
      } catch (e) {}

      const pdfBody = renderToString(<NdaPDF data={form} />);
      const styledHtml = `<div style=\"width:100%;height:100%;margin:0;padding:0;box-sizing:border-box;\">${pdfBody}</div>`;

      if ((doc as any).html) {
        await new Promise<void>((res, rej) => {
          (doc as any).html(styledHtml, {
            callback: function (doc2: any) {
              try {
                doc2.save(`nda-approval-${(form.clientName || 'client').replace(/\s+/g, '-')}.pdf`);
                res();
              } catch (e) { rej(e); }
            }, x: 0, y: 0, width: 210,
          });
        });
      } else {
        doc.text("NDA Approval - " + (form.clientName || "Client"), 10, 10);
        doc.save(`nda-approval-${(form.clientName || 'client').replace(/\s+/g, '-')}.pdf`);
      }
    } catch (e) {
      console.error(e);
      alert('Failed to generate PDF');
    } finally {
      setLoading(false);
    }
  };

  const saveApproval = async () => {
    try {
      const res = await fetch('/api/nda-approvals', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) });
      if (!res.ok) throw new Error('Failed to save');
      alert('NDA saved');
    } catch (e) {
      console.error(e);
      alert('Failed to save NDA');
    }
  };

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-4">NDA Approval Pad</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="md:col-span-2">
          <label className="block text-sm font-medium">Select Client (optional)</label>
          <Select value={selectedClientId ?? "__none__"} onValueChange={(v) => setSelectedClientId(v === "__none__" ? null : v)}>
            <SelectTrigger>
              <SelectValue>{selectedClientId ? clients.find((c) => (c._id ?? c.id) === selectedClientId)?.name : 'Choose a client'}</SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__none__">-- None --</SelectItem>
              {clients.map((c) => (
                <SelectItem key={c._id ?? c.id} value={String(c._id ?? c.id)}>{c.name} {c.companyName ? `(${c.companyName})` : ''}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div>
          <label className="block text-sm font-medium">Disclosing Party</label>
          <Input value={form.disclosingParty} onChange={(e: any) => update('disclosingParty', e.target.value)} />
        </div>
        <div>
          <label className="block text-sm font-medium">Receiving Party</label>
          <Input value={form.receivingParty} onChange={(e: any) => update('receivingParty', e.target.value)} />
        </div>

        <div>
          <label className="block text-sm font-medium">Effective Date</label>
          <Input type="date" value={form.effectiveDate} onChange={(e: any) => update('effectiveDate', e.target.value)} />
        </div>
        <div>
          <label className="block text-sm font-medium">Term</label>
          <Input value={form.term} onChange={(e: any) => update('term', e.target.value)} />
        </div>

        <div className="md:col-span-2">
          <label className="block text-sm font-medium">Scope / Description</label>
          <Textarea rows={6} value={form.scope} onChange={(e: any) => update('scope', e.target.value)} />
        </div>

        <div className="md:col-span-2">
          <label className="block text-sm font-medium">Confidential Definition</label>
          <Textarea rows={4} value={form.confidentialDefinition} onChange={(e: any) => update('confidentialDefinition', e.target.value)} />
        </div>

        <div className="md:col-span-2">
          <label className="block text-sm font-medium">Exclusions</label>
          <Textarea rows={3} value={form.exclusions} onChange={(e: any) => update('exclusions', e.target.value)} />
        </div>

        <div>
          <label className="block text-sm font-medium">Signature Name</label>
          <Input value={form.signatureName} onChange={(e: any) => update('signatureName', e.target.value)} />
        </div>
        <div>
          <label className="block text-sm font-medium">Signature Date</label>
          <Input type="date" value={form.date} onChange={(e: any) => update('date', e.target.value)} />
        </div>

        <div className="md:col-span-2 flex items-center gap-3 mt-4">
          <Button onClick={generatePdf} disabled={loading}>{loading ? 'Generating…' : 'Generate PDF'}</Button>
          <Button onClick={saveApproval} variant="default">Save Approval</Button>
          <Button variant="ghost" onClick={() => setForm({ title: 'NDA Approval', clientName: '', disclosingParty: '', receivingParty: '', effectiveDate: new Date().toISOString().split('T')[0], term: '2 years', scope: '', confidentialDefinition: '', exclusions: '', signatureName: '', date: new Date().toISOString().split('T')[0] })}>Reset</Button>
        </div>
      </div>
    </div>
  );
}
